package com.muthumol.player.dummy;
import java.net.*;import java.io.*;import java.util.*;import java.util.regex.*;import org.json.*;
/** Uses only the official public MSone addon, discovered from its install page. */
final class MsoneSubtitles {
 static final String ROOT="https://addon.malayalamsubtitles.org/";
 static final class Result{final String name;final byte[] bytes;Result(String n,byte[] b){name=n;bytes=b;}}
 interface Transport{byte[] get(String url,int limit)throws Exception;}
 static final class Hit{final String label,url;final int score;Hit(String l,String u,int s){label=l;url=u;score=s;}}
 static Result find(Movie movie)throws Exception{return find(movie,null);}
 static Result find(Movie movie,android.content.Context context)throws Exception{Exception failure=null;int count=0;for(Hit hit:search(context,movie)){if(++count>5)break;try{Result result=download(movie,hit,MsoneSubtitles::fetch);if(result!=null)return result;}catch(Exception e){failure=e;}}if(failure!=null)throw failure;return null;}
 static List<Hit> search(android.content.Context context,Movie movie)throws Exception {MediaTitle title=MediaTitle.parse(movie.title);String identity=context==null?"":context.getSharedPreferences("metadata-corrections",0).getString("imdb:"+movie.cacheIdentity(),"");if(identity.isEmpty())identity=imdb(context==null?title:MediaTitle.parse(MovieDetails.override(context,movie)));return search(movie,identity,MsoneSubtitles::fetch);}
 static List<Hit> search(Movie movie,String identity,Transport net)throws Exception{if(!identity.matches("tt[0-9]{5,10}"))throw new IOException("Title could not be identified uniquely. Correct its title / IMDb match first.");MediaTitle t=MediaTitle.parse(movie.title);String landing=new String(net.get(ROOT,512*1024),"UTF-8"),manifest="";JSONObject config;if(landing.trim().startsWith("{")){manifest=ROOT+"manifest.json";config=new JSONObject(landing);}else{Matcher matcher=Pattern.compile("(?:https://|stremio://)addon\\.malayalamsubtitles\\.org/[^\\s\"'<>]*manifest\\.json").matcher(landing.replace("&amp;","&"));if(matcher.find())manifest=matcher.group().replaceFirst("^stremio:","https:");if(manifest.isEmpty())throw new IOException("MSone addon configuration unavailable");config=new JSONObject(new String(net.get(manifest,512*1024),"UTF-8"));}if(!allowed(new URL(manifest))||!config.has("resources"))throw new IOException("MSone manifest unavailable");String base=manifest.substring(0,manifest.lastIndexOf('/')+1),id=identity+(t.episodic()?":"+t.season+":"+t.episode:"");JSONObject response=new JSONObject(new String(net.get(base+"subtitles/"+(t.episodic()?"series":"movie")+"/"+URLEncoder.encode(id,"UTF-8")+".json",1024*1024),"UTF-8"));return hits(movie,response);}
 static List<Hit> hits(Movie movie,JSONObject response)throws Exception {List<Hit> result=new ArrayList<>();JSONArray subtitles=response.optJSONArray("subtitles");if(subtitles==null)return result;Set<String> seen=new HashSet<>();MediaTitle wanted=MediaTitle.parse(movie.title);for(int i=0;i<Math.min(100,subtitles.length());i++){JSONObject sub=subtitles.optJSONObject(i);if(sub==null)continue;String lang=sub.optString("lang").toLowerCase(Locale.ROOT);if(!lang.equals("mal")&&!lang.equals("ml")&&!lang.equals("malayalam"))continue;String url=sub.optString("url");try{if(!allowed(new URL(url))||!seen.add(url))continue;}catch(Exception e){continue;}String label=sub.optString("name",sub.optString("label",sub.optString("fileName","Malayalam · MSone release "+(i+1))));MediaTitle candidate=AutoSubtitles.title(label);if(candidate.episodic()&&(!wanted.episodic()||candidate.season!=wanted.season||candidate.episode!=wanted.episode)||wanted.year>0&&candidate.year>0&&wanted.year!=candidate.year)continue;boolean wrong=false;for(String field:new String[]{"season","episode","year"})if(sub.has(field)&&!sub.isNull(field)){int expected=field.equals("year")?wanted.year:field.equals("season")?wanted.season:wanted.episode;if((field.equals("year")?expected>0:wanted.episodic())&&sub.optInt(field,-1)>=0&&sub.optInt(field,-1)!=expected)wrong=true;}if(candidate.episodic()&&MediaTitle.similarity(wanted.name,candidate.name)<.85&&!AutoSubtitles.anonymousEpisode(label))wrong=true;if(!wrong)result.add(new Hit(label,url,AutoSubtitles.releaseScore(movie.title,label)));}result.sort((a,b)->Integer.compare(b.score,a.score));return result;}
 static Result download(Movie movie,Hit hit,Transport net)throws Exception{byte[] bytes=net.get(hit.url,16*1024*1024);String path=URLDecoder.decode(new URL(hit.url).getPath(),"UTF-8"),name=path.substring(path.lastIndexOf('/')+1);if(bytes.length>3&&bytes[0]=='P'&&bytes[1]=='K'){if(!AutoSubtitles.pack(movie,name)){MediaTitle title=MediaTitle.parse(movie.title);name=title.name+(title.episodic()?" Season "+title.season:"")+".zip";}}else if(!AutoSubtitles.subtitle(name)){String start=new String(bytes,0,Math.min(512,bytes.length),java.nio.charset.StandardCharsets.UTF_8);name=start.contains("[Script Info]")?"MSone.ass":start.contains("WEBVTT")?"MSone.vtt":"MSone.srt";}AutoSubtitles.Packed result=AutoSubtitles.prepare(bytes,movie,name);return result==null?null:new Result(result.name,result.bytes);}
 static void choose(PlayerActivity a){Movie selected=a.movie();android.app.AlertDialog loading=Ui.dialog(a).setTitle("MSone subtitles").setMessage("Searching releases…").setNegativeButton("Cancel",null).show();a.session.autoSubtitles.worker.execute(()->{try{List<Hit> hits=search(a,selected);a.ui.post(()->{if(!loading.isShowing())return;loading.dismiss();if(hits.isEmpty()){Ui.message(a,"MSone","No matching releases found.");return;}String[] labels=new String[hits.size()];for(int i=0;i<labels.length;i++)labels[i]=hits.get(i).label;Ui.menu(a,"Malayalam subtitles · MSone",labels,n->a.session.autoSubtitles.worker.execute(()->{try{Result result=download(selected,hits.get(n),MsoneSubtitles::fetch);if(result==null)throw new IOException("No readable matching subtitle in this release");File folder=new File(a.getCacheDir(),"msone");folder.mkdirs();File file=new File(folder,result.name.replaceAll("[^a-zA-Z0-9._-]","_"));SmallFileIO.write(file,result.bytes);a.ui.post(()->{if(!a.movie().cacheIdentity().equals(selected.cacheIdentity()))return;a.session.autoSubtitles.generation++;a.importSubtitle(android.net.Uri.fromFile(file),result.name);});}catch(Exception e){a.ui.post(()->Ui.message(a,"MSone",e.getMessage()));}}));});}catch(Exception e){a.ui.post(()->{if(!loading.isShowing())return;loading.dismiss();Ui.dialog(a).setTitle("MSone unavailable").setMessage(e.getMessage()).setPositiveButton("Open MSone website",(d,w)->{try{a.startActivity(new android.content.Intent(android.content.Intent.ACTION_VIEW,android.net.Uri.parse("https://malayalamsubtitles.org/?s="+android.net.Uri.encode(MediaTitle.parse(selected.title).name))));}catch(Exception ignored){}}).setNeutralButton("Import subtitle file",(d,w)->a.importSubtitle()).setNegativeButton("Close",null).show();});}});}
 static String imdb(MediaTitle t)throws Exception{if(t.episodic()){JSONArray results=new JSONArray(new String(ArtworkStore.fetch("https://api.tvmaze.com/search/shows?q="+ArtworkStore.enc(t.name),512*1024),"UTF-8"));Set<String> matches=new HashSet<>();for(int i=0;i<results.length();i++){JSONObject show=results.getJSONObject(i).getJSONObject("show");if(MediaTitle.similarity(t.name,show.optString("name"))<.95||t.year>0&&!show.optString("premiered").startsWith(t.year+""))continue;JSONObject external=show.optJSONObject("externals");String id=external==null?"":external.optString("imdb");if(id.matches("tt[0-9]{5,10}"))matches.add(id);}return matches.size()==1?matches.iterator().next():"";}String q=t.name+(t.year>0?" "+t.year:"")+" film";JSONObject response=new JSONObject(new String(ArtworkStore.fetch("https://en.wikipedia.org/w/api.php?action=query&format=json&formatversion=2&generator=search&gsrsearch="+ArtworkStore.enc(q)+"&gsrlimit=5&prop=extlinks%7Cextracts&exintro=1&explaintext=1&exchars=250&ellimit=20&elquery=imdb.com%2Ftitle%2F",512*1024),"UTF-8"));JSONObject query=response.optJSONObject("query");JSONArray pages=query==null?null:query.optJSONArray("pages");if(pages!=null)for(int i=0;i<pages.length();i++){JSONObject page=pages.getJSONObject(i);String name=page.optString("title");if(MediaTitle.similarity(t.name,name.replaceAll("\\s*\\([^)]*\\)",""))<.85||t.year>0&&!name.contains(""+t.year)&&!page.optString("extract").contains(""+t.year))continue;JSONArray links=page.optJSONArray("extlinks");if(links==null)continue;for(int n=0;n<links.length();n++){Matcher match=Pattern.compile("imdb\\.com/title/(tt[0-9]+)").matcher(links.getJSONObject(n).optString("url"));if(match.find())return match.group(1);}}return "";}
 static boolean allowed(URL u){String host=u.getHost().toLowerCase(Locale.ROOT);return u.getProtocol().equals("https")&&(u.getPort()==-1||u.getPort()==443)&&u.getUserInfo()==null&&(host.equals("malayalamsubtitles.org")||host.endsWith(".malayalamsubtitles.org"));}
 static byte[] fetch(String raw,int limit)throws Exception{URL u=new URL(raw);for(int redirect=0;redirect<4;redirect++){if(!allowed(u))throw new IOException("Untrusted subtitle host");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(5000);c.setReadTimeout(8000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","TGstream/6.1");try{int code=c.getResponseCode();if(code>=300&&code<400){u=new URL(u,c.getHeaderField("Location"));continue;}if(code!=200)throw new IOException("MSone unavailable (HTTP "+code+")");if(c.getContentLength()>limit)throw new IOException("Subtitle response too large");try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>limit)throw new IOException("Subtitle response too large");out.write(buffer,0,n);}return out.toByteArray();}}finally{c.disconnect();}}throw new IOException("Too many subtitle redirects");}
}
